async function start(){
const {statuses,label,nextStep,milestones,canCancel,sumCentavos,stockExpired,cancellationChecks}=await import('/ui.mjs');
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
let config={},me=null,csrf='',draft=null,offers=[],customers=[],order=null,quote=null,epoch=0,stage=1,page=1,noticeTimer;
const busy=new Set(),PAGE_SIZE=10;
const validQuantity=n=>Number.isSafeInteger(n)&&n>0&&n<=100000;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const peso=value=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(Number(value||0));
const cents=value=>{const [w,f='']=String(value||'0').split('.');return Number(w)*100+Number(f.padEnd(2,'0'));};
const selected=(a,b)=>String(a)===String(b)?' selected':'';
const isStaff=()=>me?.role==='staff';
const listTitle=()=>isStaff()?'Sales & orders':'My orders';
const paths={orders:'M4 5h16v16H4z M8 5V3h8v2 M8 10h8 M8 14h8 M8 18h5',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',box:'m3 7 9-4 9 4v10l-9 4-9-4z M3 7l9 4 9-4 M12 11v10',check:'m5 12 4 4 10-10',card:'M3 5h18v14H3z M3 9h18 M7 15h4',truck:'M2 6h12v12H2z M14 10h4l4 4v4h-8 M5 18a2 2 0 1 0 4 0 M16 18a2 2 0 1 0 4 0',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',chevron:'m9 5 7 7-7 7',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',alert:'m12 3 10 18H2z M12 9v5 M12 17h.01',refresh:'M20 7V3l-4 4 M20 7a9 9 0 1 0 1 8',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7 M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',logout:'M10 4H4v16h6 M10 12h11 M17 8l4 4-4 4',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-3a8 8 0 0 1 16 0v3',close:'m6 6 12 12 M6 18 18 6',back:'M19 12H5 M10 7l-5 5 5 5',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`;
const action=(name,text,kind='',attrs='')=>`<button type="button" data-action="${name}" class="${kind}" ${attrs}>${text}</button>`;
const link=(href,text,kind='')=>`<a class="button ${kind}" href="${href}">${text}</a>`;
const badge=status=>`<span class="badge ${statuses.includes(status)?status:''}"><span class="status-dot"></span>${esc(label(status))}</span>`;
function date(value,withTime=false){if(!value)return '—';const d=new Date(value.includes('T')?value:value.replace(' ','T')+'Z');return Number.isNaN(d.valueOf())?'—':d.toLocaleString('en-PH',{month:'short',day:'numeric',year:'numeric',...(withTime?{hour:'numeric',minute:'2-digit'}:{}),timeZone:'Asia/Manila'});}
function toast(message){const el=document.querySelector('#notice');el.textContent=message;el.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>el.classList.remove('show'),5500);}
async function api(path,method='GET',data){let response;try{response=await fetch('/api'+path,{method,headers:{'content-type':'application/json','x-csrf-token':csrf},body:data===undefined?undefined:JSON.stringify(data)});}catch{throw new Error('We couldn’t connect. Check your connection and try again.');}let result;try{result=await response.json();}catch{throw new Error('We couldn’t read the server response. Try again.');}if(!response.ok){if(response.status===401&&me){me=null;login();}const error=new Error(response.status>=500&&!isStaff()?'We couldn’t complete that request. Please try again or contact the sales team.':result.error||'Request failed.');error.details=result.details;error.status=response.status;throw error;}return result;}
async function processing(key,button,work,text='Working…'){
 if(busy.has(key))return;busy.add(key);if(key==='draft-mutation')captureDraft();
 const targets=key==='login'?[...document.querySelectorAll('#login-form button[type="submit"],[data-action="demo-login"]')]:button?[button]:[];
 const before=targets.map(b=>({b,html:b.innerHTML,disabled:b.disabled}));targets.forEach(b=>{b.disabled=true;b.setAttribute('aria-busy','true');});if(button)button.textContent=text;
 try{return await work();}finally{busy.delete(key);before.forEach(({b,html,disabled})=>{if(b.isConnected){b.innerHTML=html;b.disabled=disabled;b.removeAttribute('aria-busy');}});}
}
const fieldError=(name)=>`<span class="field-error" id="error-${name}" data-error-for="${name}" aria-live="polite"></span>`;
function showErrors(errors,root=document){root.querySelectorAll('[data-error-for]').forEach(e=>e.textContent='');root.querySelectorAll('[aria-invalid]').forEach(e=>e.removeAttribute('aria-invalid'));let first;for(const[name,message]of Object.entries(errors)){const el=root.querySelector(`[name="${name}"]`),target=root.querySelector(`[data-error-for="${name}"]`);if(target)target.textContent=message;if(el){el.setAttribute('aria-invalid','true');first??=el;}}first?.focus();return !Object.keys(errors).length;}
function formError(message,root=document){const target=root.querySelector('[data-form-error]');if(target){target.textContent=message;target.hidden=!message;target.focus();}else toast(message);}
function headingFocus(){document.querySelector('main h1')?.focus({preventScroll:true});}
function shell(content,section='orders'){
 const nav=(href,name,symbol,key)=>`<a href="${href}" class="nav-link ${section===key?'active':''}" ${section===key?'aria-current="page"':''}>${icon(symbol)}<span>${name}</span></a>`;
 app.innerHTML=`<a href="#main-content" class="skip-link">Skip to content</a><aside class="sidebar"><a class="brand" href="#orders"><span class="brand-mark">${icon('box')}</span><span>Campus<span class="brand-light">ERP</span><small>SALES & ORDER MANAGEMENT</small></span></a><div class="nav-caption">${isStaff()?'SALES WORKSPACE':'YOUR WORKSPACE'}</div><nav aria-label="Main navigation">${nav('#orders',listTitle(),'orders','orders')}${nav('#new','Create order','plus','new')}${isStaff()?nav('#operations',config.demo?'Demo operations':'Integrations','settings','operations'):''}</nav><div class="sidebar-help">${icon('check')}<p>One workspace.<br>Every order, a clear next step.</p></div><div class="sidebar-foot"><div class="account"><span class="avatar">${esc(me.email.slice(0,2).toUpperCase())}</span><div><strong title="${esc(me.email)}">${esc(me.email)}</strong><small>${isStaff()?'Sales team':'Customer account'}</small></div></div>${action('logout',icon('logout')+'Sign out','quiet')}</div></aside><div class="workspace"><header class="topbar"><span>CampusERP <span class="breadcrumb">/</span> <strong>${section==='new'?'Create order':section==='operations'?config.demo?'Demo operations':'Integrations':listTitle()}</strong></span><div class="topbar-actions">${config.demo?'<span class="environment"><span class="status-dot"></span>Demo · Simulated</span>':'<span class="live-label">Sales workspace</span>'}${action('logout',icon('logout')+'<span>Sign out</span>','quiet mobile-signout')}</div></header><main class="content" id="main-content" tabindex="-1">${content}</main><footer class="app-footer"><span>CampusERP · Sales & Order Management</span><span>${config.demo?'Local demo. Service results are simulated.':'Product totals are shown in PHP.'}</span></footer></div>`;
}
function login(error='',email=''){
 app.innerHTML=`<main class="login"><section class="login-story"><a class="brand" href="#"><span class="brand-mark">${icon('box')}</span><span>Campus<span class="brand-light">ERP</span><small>SALES & ORDER MANAGEMENT</small></span></a><div class="story-content"><div class="eyebrow">FROM FIRST ITEM TO FINAL DELIVERY</div><h1>Every order.<br>A clear next step.</h1><p>A simple place to create purchases, follow progress, and keep the details together.</p><ol class="process-illustration" aria-label="The order process">${[['orders','Order','Build your purchase'],['box','Reservation','Check stock availability'],['card','Payment','Wait for verified payment'],['truck','Delivery','Track through confirmation']].map(([i,t,s],n)=>`<li><span class="process-icon">${icon(i)}</span><div><strong>${t}</strong><small>${s}</small></div><span class="process-index">0${n+1}</span></li>`).join('')}</ol></div><p class="login-footer">University MiniERP project <span>Sales module</span></p></section><section class="login-form"><div class="login-card"><div class="eyebrow">WELCOME TO YOUR WORKSPACE</div><h2>Welcome back.</h2><p>Sign in to create orders and follow their progress.</p><form id="login-form" novalidate><div class="error" id="login-error" role="alert" data-form-error tabindex="-1" ${error?'':'hidden'}>${esc(error)}</div><label>Email address<input name="email" type="email" autocomplete="username" value="${esc(email)}" placeholder="you@example.edu" aria-describedby="error-email" required>${fieldError('email')}</label><label>Password<span class="password-control"><input id="password-input" name="password" type="password" autocomplete="current-password" placeholder="Enter your password" aria-describedby="error-password" required maxlength="200">${action('toggle-password',icon('eye')+'<span>Show</span>','password-toggle','aria-label="Show password" aria-pressed="false" aria-controls="password-input"')}</span>${fieldError('password')}</label><button class="primary full" type="submit">Sign in ${icon('arrow')}</button></form>${config.demo?`<details class="demo-accounts"><summary>Try a demo account <span>Local demo</span></summary><p>Select an account to sign in instantly with fictional demo data. No real payments or shipments are created.</p><div class="demo-users">${[['admin@example.test','Sales team','Manage demo orders'],['alex@example.test','Alex Santos','View Alex’s orders'],['jamie@example.test','Jamie Reyes','View Jamie’s orders']].map(([email,name,help])=>action('demo-login',`<span class="avatar">${icon(email.startsWith('admin')?'orders':'user')}</span><span><strong>${name}</strong><small>${help}</small></span>${icon('arrow')}`,'demo-account',`data-email="${email}"`)).join('')}</div><small class="demo-credentials">Demo password: <code>CampusDemo2026!</code></small></details>`:''}<p class="login-note">${icon('check')}Access is based on your signed-in account.</p></div></section></main>`;
 document.title='Sign in · CampusERP';
}
async function signIn(email,password){const result=await api('/login','POST',{email,password});me=result.user;csrf=result.csrf;page=1;sessionStorage.removeItem('orderFilters');if(location.hash!=='#orders')location.hash='orders';else await route();}
const skeleton=()=>`<div class="loading" role="status" aria-label="Loading workspace"><span class="spinner"></span> Loading your workspace…</div><div class="skeleton-cards" aria-hidden="true"><i></i><i></i><i></i><i></i></div><div class="skeleton-panel" aria-hidden="true"></div>`;
async function route(){
 if(!me)return login();modal.close();const ticket=++epoch,hash=location.hash.slice(1)||'orders';shell(skeleton(),hash==='operations'?'operations':hash==='new'||hash.startsWith('edit/')?'new':'orders');
 try{
  if(hash==='orders')await orderList(ticket);
  else if(hash==='new'||/^edit\/\d+$/.test(hash)){
   const data=await Promise.all([api('/offers'),api('/customers')]);if(ticket!==epoch)return;[offers,customers]=data;
   if(hash.startsWith('edit/')){order=await api('/orders/'+hash.split('/')[1]);if(ticket!==epoch)return;if(order.order_status!=='draft')throw new Error('This order is already submitted and its purchase details are locked.');draft={...order,items:order.items.map(i=>({offer_id:i.offer_id,quantity:i.quantity}))};}
   else{order=null;draft={customer_id:isStaff()?customers[0]?.customer_id||'':me.customer_id,seller_id:offers[0]?.seller_id||'',items:[],recipient_name:'',recipient_contact:'',requested_delivery_address:''};}
   stage=1;quote=null;draftView();
  }else if(/^order\/\d+$/.test(hash)){order=await api('/orders/'+hash.split('/')[1]);if(ticket!==epoch)return;detailView();}
  else if(hash==='operations'){const requests=await api('/operations/requests');if(ticket!==epoch)return;operations(requests);}
  else{location.hash='orders';return;}
  if(ticket===epoch){document.title=`${document.querySelector('main h1')?.textContent||'Orders'} · CampusERP`;headingFocus();}
 }catch(error){if(ticket===epoch&&me)shell(`<div class="empty error-state">${icon('alert')}<h1 tabindex="-1">We couldn’t load this page</h1><p>${esc(error.message)}</p><div class="actions">${action('refresh',icon('refresh')+'Try again','primary')}${link('#orders','Back to orders')}</div></div>`);}
}
const filters=()=>new URLSearchParams(sessionStorage.getItem('orderFilters')||'');
async function orderList(ticket){
 const params=filters(),[all,rows]=await Promise.all([api('/orders'),api('/orders?'+params)]);if(ticket!==epoch)return;
 const active=rows.filter(o=>!['draft','cancelled','completed'].includes(o.order_status));
 const submitted=rows.filter(o=>!['draft','cancelled'].includes(o.order_status));
 const totalPages=Math.max(1,Math.ceil(rows.length/PAGE_SIZE));page=Math.min(page,totalPages);const visible=rows.slice((page-1)*PAGE_SIZE,page*PAGE_SIZE);
 const chips=[['','All'],['draft','Drafts'],['pending_stock','Pending stock'],['awaiting_payment','Awaiting payment'],['completed','Completed']];
 const applied=[...params].map(([key,v])=>`<span class="filter-chip">${esc({search:'Search',status:'Status',from:'From',to:'To'}[key])}: ${esc(key==='status'?label(v):v)}</span>`).join('');
 const row=o=>`<tr><td><a class="order-number" href="#order/${o.order_id}">${esc(o.order_number)}</a><small>${esc(o.seller_name)} · ${o.item_count} ${Number(o.item_count)===1?'item':'items'}</small>${isStaff()?`<small>${esc(o.customer_name)}</small>`:''}</td><td>${badge(o.order_status)}<small class="next-step">${esc(nextStep(o,isStaff()))}</small></td><td>${date(o.created_at)}<small>Updated ${date(o.updated_at)}</small></td><td class="amount"><strong>${peso(o.order_total)}</strong></td><td class="row-action"><a href="#order/${o.order_id}" class="view-link">View order ${icon('chevron')}</a></td></tr>`;
 shell(`<div class="page-head"><div><div class="eyebrow">${isStaff()?'SALES WORKSPACE':'YOUR ORDER WORKSPACE'}</div><h1 tabindex="-1">${listTitle()}</h1><p>${isStaff()?'Manage purchases and keep every order moving.':'Create an order, continue a draft, or follow a delivery.'}</p></div>${link('#new',icon('plus')+'Create order','primary')}</div><div class="stats"><div class="stat"><span class="stat-icon">${icon('orders')}</span><small>Total orders</small><strong>${rows.length}</strong></div><div class="stat feature"><span class="stat-icon">${icon('box')}</span><small>Active orders</small><strong>${active.length}</strong></div><div class="stat"><span class="stat-icon">${icon('card')}</span><small>Awaiting payment</small><strong>${rows.filter(o=>o.order_status==='awaiting_payment').length}</strong></div><div class="stat"><span class="stat-icon">${icon('check')}</span><small>Submitted product value</small><strong class="value">${peso(sumCentavos(submitted)/100)}</strong></div></div><p class="scope-note">Summary: matching filters, up to 500 most recent ${isStaff()?'permitted orders':'orders in your account'}. Product value excludes drafts and cancellations; it is not payment received.</p>${isStaff()&&all.some(o=>o.reconciliation)?`<div class="attention-note">${icon('alert')}<span><strong>${all.filter(o=>o.reconciliation).length} ${all.filter(o=>o.reconciliation).length===1?'order needs':'orders need'} attention.</strong> Open the flagged orders to review service results.</span></div>`:''}<section class="panel"><div class="panel-head"><div><h2>${isStaff()?'Order workspace':'Your orders'}</h2><p>Find a purchase or pick up where you left off.</p></div><span class="result-count">${rows.length} ${rows.length===1?'result':'results'}</span></div><nav class="status-tabs" aria-label="Order status shortcuts">${chips.map(([value,name])=>action('status-filter',`${name}<span>${value?all.filter(o=>o.order_status===value).length:all.length}</span>`,'status-tab'+((params.get('status')||'')===value?' active':''),`data-status="${value}" aria-pressed="${(params.get('status')||'')===value}"`)).join('')}</nav><div class="filter-scope">Created date filters use UTC; displayed dates use Philippine time. Shortcut counts cover the most recent 500 ${isStaff()?'permitted orders':'orders in your account'} before filters.</div><form class="toolbar" id="filter-form" novalidate><label class="search-field">Search orders<span class="search-control">${icon('search')}<input name="search" placeholder="${isStaff()?'Order number or customer':'Order number'}" value="${esc(params.get('search')||'')}" maxlength="150"></span></label><label>Status<select name="status"><option value="">All statuses</option>${statuses.map(s=>`<option value="${s}"${selected(s,params.get('status'))}>${label(s)}</option>`).join('')}</select></label><label>Created from<input type="date" name="from" value="${esc(params.get('from')||'')}"></label><label>Created to<input type="date" name="to" value="${esc(params.get('to')||'')}"></label><div class="filter-buttons"><button class="primary" type="submit">Apply</button>${action('reset-filters','Reset','quiet')}</div><div class="field-error span-all" data-error-for="dates" role="alert"></div></form>${params.size?`<div class="active-filters" aria-label="Active filters">${applied}${action('reset-filters','Clear all','link')}</div>`:''}${rows.length?`<div class="desktop-orders table-wrap"><table><thead><tr><th>${isStaff()?'Order / customer':'Order / seller'}</th><th>Status & next step</th><th>Created / updated</th><th class="amount">Product total</th><th><span class="sr-only">Action</span></th></tr></thead><tbody>${visible.map(row).join('')}</tbody></table></div><div class="mobile-orders">${visible.map(o=>`<article class="order-card"><div class="card-top"><a class="order-number" href="#order/${o.order_id}">${esc(o.order_number)}</a>${badge(o.order_status)}</div><p>${esc(o.seller_name)} · ${o.item_count} items${isStaff()?' · '+esc(o.customer_name):''}</p><div class="card-next">${icon('clock')}${esc(nextStep(o,isStaff()))}</div><div class="card-bottom"><div><strong>${peso(o.order_total)}</strong><small>${date(o.created_at)}</small></div><a class="view-link" href="#order/${o.order_id}">View order ${icon('chevron')}</a></div></article>`).join('')}</div><div class="table-foot"><span>Showing ${(page-1)*PAGE_SIZE+1}–${Math.min(page*PAGE_SIZE,rows.length)} of ${rows.length}</span><div class="pagination">${action('page-prev','Previous','','aria-label="Previous page" '+(page===1?'disabled':''))}<span>Page ${page} of ${totalPages}</span>${action('page-next','Next','','aria-label="Next page" '+(page===totalPages?'disabled':''))}</div></div>`:`<div class="empty"><span class="empty-icon">${icon(params.size?'search':'orders')}</span><h3>${params.size?'No matching orders':isStaff()?'Ready for your first order?':'Your orders start here'}</h3><p>${params.size?'Try another search, change the date range, or clear your filters.':isStaff()?'Choose a customer, build a draft, and follow its next steps.':'Create your first order and track its progress here.'}</p>${params.size?action('reset-filters','Clear filters','primary'):link('#new',icon('plus')+'Create an order','primary')}</div>`}</section>`);
}
function captureDraft(){const form=document.querySelector('#draft-form');if(form){for(const[key,value]of new FormData(form))draft[key]=value;if(isStaff())draft.customer_id=Number(draft.customer_id);}if(draft&&!isStaff())draft.customer_id=me.customer_id;}
function selectedItems(){return draft.items.map(i=>{const offer=offers.find(o=>o.offer_id===i.offer_id);return {...i,...offer,unit:offer?cents(offer.selling_price):0,name:offer?.product_name||`Unavailable offer #${i.offer_id}`};});}
function stageIndicator(){return `<ol class="stages" aria-label="Create order stages">${['Select items','Recipient details','Review order'].map((name,i)=>`<li class="${stage===i+1?'current':stage>i+1?'done':''}" ${stage===i+1?'aria-current="step"':''}>${action('stage',`<span class="stage-number">${stage>i+1?icon('check'):i+1}</span><span>${name}</span>`,'',`data-stage="${i+1}" ${i+1>stage?'disabled':''}`)}</li>`).join('')}</ol>`;}
function summary(){
 const items=stage===3&&quote?quote.items.map(i=>({name:i.product_name_at_order,quantity:i.quantity,unit:cents(i.unit_price_at_order)})):selectedItems();
 const total=items.reduce((s,i)=>s+i.unit*(validQuantity(i.quantity)?i.quantity:0),0),seller=offers.find(o=>o.seller_id===Number(draft.seller_id))?.seller_name||'Choose a seller';
 return `<aside class="summary-column"><section class="panel summary"><div class="panel-head"><h2>Order summary</h2><span class="summary-icon">${icon('orders')}</span></div><div class="panel-body"><div class="summary-seller"><small>SELLER</small><strong>${esc(seller)}</strong></div>${items.length?items.map(i=>`<div class="summary-item"><div>${esc(i.name)}<small>${i.quantity} × ${peso(i.unit/100)}</small></div><strong>${peso(i.unit*i.quantity/100)}</strong></div>`).join(''):'<p class="summary-empty">Your selected products will appear here.</p>'}<div class="summary-row total"><span>Product total</span><strong>${peso(total/100)}</strong></div><p class="money-note">PHP · Shipping, tax, and discounts are not included.</p>${stage===3?'<p class="note">Check the purchase details and accept the current prices to submit.</p>':action('stage-next',`Continue ${icon('arrow')}`,'primary full')}<div class="summary-assurance">${icon('check')}Prices are checked by the server before submission.</div></div></section></aside>`;
}
function itemsTable(){const items=selectedItems();return items.length?`<div class="selected-items">${items.map(i=>`<div class="selected-item"><span class="product-placeholder">${icon('box')}</span><div class="selected-name"><strong>${esc(i.name)}</strong><small>${offers.some(o=>o.offer_id===i.offer_id)?peso(i.unit/100)+' per unit':'No longer available'}</small></div><label class="quantity-label">Quantity<input type="number" min="1" max="100000" step="1" value="${i.quantity}" data-quantity="${i.offer_id}" aria-label="Quantity for ${esc(i.name)}" aria-describedby="quantity-${i.offer_id}"><span id="quantity-${i.offer_id}" class="sr-only">Positive whole numbers, up to 100,000</span></label><strong class="item-total">${peso(i.unit*i.quantity/100)}</strong>${action('remove-item',icon('close'),'icon-button',`data-id="${i.offer_id}" aria-label="Remove ${esc(i.name)}"`)}</div>`).join('')}</div>`:'<div class="small-empty">No items selected. Add a product from the list above.</div>';}
function recipientFields(){return `<form id="draft-form" class="form-grid" novalidate><div class="error span-all" data-form-error role="alert" tabindex="-1" hidden></div>${isStaff()?`<label class="span-all">Customer<select name="customer_id" required aria-describedby="error-customer_id"><option value="">Select a customer</option>${customers.map(c=>`<option value="${c.customer_id}"${selected(c.customer_id,draft.customer_id)}>${esc(c.customer_name)} · ${esc(c.contact_number)}</option>`).join('')}</select>${fieldError('customer_id')}</label><div class="span-all">${action('new-customer',icon('plus')+'Add a customer','link')}</div>`:`<div class="customer-identity span-all">${icon('user')}<span>Ordering as <strong>${esc(customers.find(c=>c.customer_id===me.customer_id)?.customer_name||me.email)}</strong><small>Your order is linked to your signed-in account.</small></span></div>`}<label>Recipient name<input name="recipient_name" maxlength="150" value="${esc(draft.recipient_name)}" placeholder="Full name" autocomplete="name" required aria-describedby="error-recipient_name">${fieldError('recipient_name')}</label><label>Contact number<input name="recipient_contact" maxlength="30" value="${esc(draft.recipient_contact)}" placeholder="09XX XXX XXXX" type="tel" autocomplete="tel" required aria-describedby="error-recipient_contact">${fieldError('recipient_contact')}</label><label class="span-all">Delivery address<textarea name="requested_delivery_address" maxlength="3000" autocomplete="street-address" placeholder="House / building, street, barangay, city, province, postal code" required aria-describedby="error-requested_delivery_address">${esc(draft.requested_delivery_address)}</textarea>${fieldError('requested_delivery_address')}</label><p class="field-hint span-all">Use the recipient and address where you want this order delivered.</p></form>`;}
function reviewContent(inModal=false){const q=quote, o=inModal?order:draft;const changed=q.order_total!==String(o.order_total)||q.items.some(i=>i.unit_price_at_order!==String(order?.items.find(x=>x.offer_id===i.offer_id)?.unit_price_at_order)||i.product_name_at_order!==order?.items.find(x=>x.offer_id===i.offer_id)?.product_name_at_order);return `<div class="error" data-form-error role="alert" tabindex="-1" hidden></div><div class="note ${changed?'warning':''}">${icon(changed?'alert':'check')}<span>${changed?'The current names or prices differ from the saved draft. Review the revised details and explicitly accept them.':'Current product names, prices, and availability have been checked by the server.'}</span></div><div class="review-recipient"><small>DELIVER TO</small><strong>${esc(o.recipient_name)}</strong><span>${esc(o.recipient_contact)}</span><p>${esc(o.requested_delivery_address)}</p>${action(inModal?'edit-draft':'stage','Edit recipient details','link',inModal?'':'data-stage="2"')}</div><div class="review-items">${q.items.map(i=>`<div class="review-line"><div><strong>${esc(i.product_name_at_order)}</strong><small>${i.quantity} × ${peso(i.unit_price_at_order)}</small></div><strong>${peso(cents(i.unit_price_at_order)*i.quantity/100)}</strong></div>`).join('')}</div><div class="summary-row total"><span>Product total</span><strong>${peso(q.order_total)}</strong></div><p class="money-note">No shipping, tax, or discounts are added.</p><label class="check acceptance"><input type="checkbox" id="accept-prices"><span>I accept the product names, quantities, current prices, and total shown above.</span></label><p class="field-error" data-error-for="acceptance" aria-live="polite"></p><div class="review-actions">${inModal?action('close-modal','Back'):action('stage','Back to recipient','','data-stage="2"')}${action('submit-order',`Submit order ${icon('arrow')}`,'primary','disabled')}</div>`;}
function draftView(focus){
 const sellers=[...new Map(offers.map(o=>[o.seller_id,o])).values()],choices=offers.filter(o=>o.seller_id===Number(draft.seller_id));
 let content;
 if(stage===1)content=`<section class="panel"><div class="panel-head"><div><h2>Select your products</h2><p>One seller per order. Add the same offer again to increase its quantity.</p></div><span class="step-label">STEP 1 OF 3</span></div><div class="panel-body"><label>Seller<select id="seller-select" aria-describedby="seller-help"><option value="" ${draft.seller_id?'':'selected'} disabled>Select a seller</option>${sellers.map(s=>`<option value="${s.seller_id}"${selected(s.seller_id,draft.seller_id)}>${esc(s.seller_name)}</option>`).join('')}</select><small id="seller-help">Changing seller clears the selected products after confirmation.</small></label><div class="error" data-form-error role="alert" tabindex="-1" hidden></div><div class="product-list">${choices.map(o=>`<article class="offer-row"><span class="product-placeholder">${icon('box')}</span><div><h3>${esc(o.product_name)}</h3><p>${esc(o.description)}</p></div><div class="offer-price"><strong>${peso(o.selling_price)}</strong><small>per unit</small></div>${action('add-item',icon('plus')+'<span>Add</span>','add-product',`data-id="${o.offer_id}" aria-label="Add ${esc(o.product_name)}"`)}</article>`).join('')||'<div class="small-empty">No active products are available from Catalogue. Please try again later.</div>'}</div></div></section><section class="panel"><div class="panel-head"><h2>Selected items</h2><span class="result-count">${draft.items.reduce((s,i)=>s+(validQuantity(i.quantity)?i.quantity:0),0)} items</span></div>${itemsTable()}</section>`;
 else if(stage===2)content=`<section class="panel"><div class="panel-head"><div><h2>Who is receiving the order?</h2><p>Add the contact and delivery details.</p></div><span class="step-label">STEP 2 OF 3</span></div><div class="panel-body">${recipientFields()}</div></section>`;
 else content=`<section class="panel"><div class="panel-head"><div><h2>Review your order</h2><p>Your draft is saved. Check everything before submitting.</p></div><span class="step-label">STEP 3 OF 3</span></div><div class="panel-body">${reviewContent()}</div></section>`;
 shell(`<a class="back" href="#orders">${icon('back')}Back to ${isStaff()?'orders':'my orders'}</a><div class="page-head"><div><div class="eyebrow">${draft.order_id?'CONTINUE YOUR PURCHASE':'BUILD A PURCHASE'}</div><h1 tabindex="-1">${draft.order_id?'Edit draft':'Create an order'}</h1><p>Select items, add a recipient, and review the current prices.</p></div>${action('save-draft',icon('orders')+'Save draft','secondary')}</div>${stageIndicator()}<div class="split draft-layout"><div>${content}<div class="stage-navigation">${stage>1&&stage<3?action('stage',icon('back')+'Back','','data-stage="1"'):'<span></span>'}${stage<3?action('stage-next',`Continue to ${stage===1?'recipient':'review'} ${icon('arrow')}`,'primary'):''}</div></div>${summary()}</div>`,'new');
 if(focus)document.querySelector(focus)?.focus({preventScroll:true});
}
function validateDraft(recipient=false){captureDraft();const errors={};if(!draft.items.length)errors.items='Add at least one product to continue.';if(draft.items.some(i=>!Number.isSafeInteger(i.quantity)||i.quantity<1||i.quantity>100000))errors.items='Use positive whole-number quantities, up to 100,000.';if(draft.items.some(i=>!offers.some(o=>o.offer_id===i.offer_id&&o.seller_id===Number(draft.seller_id))))errors.items='An item is no longer available. Remove it or select an active offer.';if(recipient){if(!draft.customer_id)errors.customer_id='Select a customer for this order.';for(const [key,name]of [['recipient_name','recipient name'],['recipient_contact','contact number'],['requested_delivery_address','delivery address']])if(!String(draft[key]||'').trim())errors[key]=`Enter the ${name}.`;}if(errors.items){formError(errors.items);return false;}return showErrors(errors);}
async function persistDraft(){captureDraft();if(!isStaff())draft.customer_id=me.customer_id;if(!draft.customer_id)throw new Error('Choose or create a customer in Recipient details before saving.');const result=await api(draft.order_id?`/orders/${draft.order_id}`:'/orders',draft.order_id?'PUT':'POST',draft);order=await api('/orders/'+result.order_id);draft={...order,items:order.items.map(i=>({offer_id:i.offer_id,quantity:i.quantity}))};return result;}
async function advanceStage(){if(stage===1){if(!validateDraft())return;stage=2;draftView();document.querySelector('#draft-form input')?.focus();}else if(stage===2){if(!validateDraft(true))return;await persistDraft();quote=await api(`/orders/${order.order_id}/review`,'POST',{});stage=3;draftView();document.querySelector('main h2')?.scrollIntoView({block:'start'});}}
function orderProgress(o){if(['draft','cancelled','cancellation_pending'].includes(o.order_status))return `<div class="progress-exception ${o.order_status==='draft'?'':'warning'}">${icon(o.order_status==='draft'?'orders':'alert')}<div><strong>${label(o.order_status)}</strong><p>${esc(nextStep(o,isStaff()))}</p>${o.order_status==='cancellation_pending'?`<div class="cancel-checks"><span>${cancellationChecks(o).unpaidVerified?icon('check'):icon('clock')}${cancellationChecks(o).paymentVerified?'Payment verified — reconciliation required':'Unpaid payment check: '+(cancellationChecks(o).unpaidVerified?'verified':'waiting')}</span><span>${cancellationChecks(o).releaseVerified?icon('check'):icon('clock')}Stock release: ${cancellationChecks(o).releaseVerified?'verified':'waiting'}</span></div>`:''}</div></div>`;return `<ol class="order-progress" aria-label="Order progress">${milestones(o).map((m,i)=>`<li class="${m.done?'done':m.active?'current':''}"><span class="milestone">${m.done?icon('check'):i+1}</span><strong>${m.name}</strong><small>${m.state}</small></li>`).join('')}</ol>`;}
function historyReason(h){if(isStaff())return h.reason;return {draft:'Your order draft was saved.',pending_stock:'Your order was submitted for stock confirmation.',awaiting_payment:'Inventory confirmed the reservation for all items.',confirmed:'Payment was verified and the stock reservation was confirmed.',fulfilling:'Delivery accepted your order.',completed:'Delivery was verified.',cancellation_pending:'Cancellation is waiting for payment checks and stock release.',cancelled:h.previous_status==='draft'?'Your draft was cancelled.':'Payment checks and stock release were verified.'}[h.new_status]||'Order progress updated.';}
function detailView(){const o=order,expired=stockExpired(o);
 shell(`<a class="back" href="#orders">${icon('back')}Back to ${isStaff()?'orders':'my orders'}</a><div class="page-head"><div><div class="eyebrow">${isStaff()?'ORDER DETAILS':'YOUR PURCHASE'}</div><h1 class="order-heading" tabindex="-1">${esc(o.order_number)}</h1><p>Created ${date(o.created_at,true)}${isStaff()?' · '+esc(o.customer_name):''}</p></div>${badge(o.order_status)}</div><div class="next-step-banner ${o.reconciliation||expired?'warning':''}">${icon(o.reconciliation||expired?'alert':'clock')}<span><strong>${o.reconciliation?'Order needs attention':'What happens next'}</strong>${esc(nextStep(o,isStaff()))}</span>${action('refresh',icon('refresh')+'Refresh','quiet')}</div>${isStaff()&&o.reconciliation?`<div class="note warning">${icon('alert')}<span>${esc(o.reconciliation)}</span></div>`:''}<section class="panel progress-panel"><div class="panel-head"><h2>Order progress</h2><small>Based on verified service updates</small></div><div class="panel-body">${orderProgress(o)}</div></section><div class="split detail-layout"><div><section class="panel"><div class="panel-head"><div><h2>Purchased items</h2><p>${esc(o.seller_name)}</p></div><span class="result-count">${o.items.reduce((s,i)=>s+i.quantity,0)} items</span></div><div class="purchase-items">${o.items.map(i=>`<div class="purchase-item"><span class="product-placeholder">${icon('box')}</span><div><strong>${esc(i.product_name_at_order)}</strong><small>${i.quantity} × ${peso(i.unit_price_at_order)}${isStaff()?' · Offer #'+i.offer_id:''}</small></div><strong>${peso(cents(i.unit_price_at_order)*i.quantity/100)}</strong></div>`).join('')||'<div class="small-empty">This draft has no items yet.</div>'}</div><div class="panel-body purchase-total"><div class="summary-row total"><span>Product total</span><strong>${peso(o.order_total)}</strong></div><p class="money-note">${o.order_status==='draft'?'Draft estimate. Current prices are checked before submission.':'Accepted product names and prices are saved with this purchase.'} No additional charges.</p></div></section><section class="panel"><div class="panel-head"><h2>Stock, payment & delivery</h2><small>Separate service confirmations</small></div><div class="facts"><div class="fact"><span class="fact-icon">${icon('box')}</span><h3>Stock reservation</h3>${badge(expired?'expired':o.stock)}<p>${o.reservation_expires?`${o.order_status==='completed'?'Reservation validity at purchase':['released','expired'].includes(o.stock)?'Original reservation deadline':'Valid until'} ${date(new Date(Number(o.reservation_expires)).toISOString(),true)}`:o.stock==='confirmed'?'Confirmed hold — no automatic expiry.':o.stock==='fulfilled'?'Stock deduction verified by Inventory.':'No stock reservation has been confirmed.'}</p></div><div class="fact"><span class="fact-icon">${icon('card')}</span><h3>Payment</h3>${badge(o.payment)}<p>${esc(o.invoice_reference||'No invoice has been created.')}${o.transaction_reference?'<br>'+esc(o.transaction_reference):''}</p></div><div class="fact"><span class="fact-icon">${icon('truck')}</span><h3>Shipment</h3>${badge(o.shipment)}<p>${esc(o.tracking_reference||'No shipment has been confirmed.')}</p></div></div></section><section class="panel"><div class="panel-head"><h2>Status history</h2><span class="result-count">${o.history.length} updates</span></div><div class="panel-body"><ol class="timeline">${o.history.map(h=>`<li><div><strong>${label(h.new_status)}</strong><time>${date(h.changed_at,true)}</time></div><p>${esc(historyReason(h))}</p>${isStaff()?`<small>Source: ${esc(h.change_source)}</small>`:''}</li>`).join('')}</ol></div></section></div><aside><section class="panel"><div class="panel-head"><h2>Recipient details</h2>${icon('user')}</div><div class="panel-body detail-meta"><strong>${esc(o.recipient_name||'Not entered')}</strong><span>${esc(o.recipient_contact||'No contact number entered')}</span><p>${esc(o.requested_delivery_address||'No address entered')}</p>${isStaff()?`<div class="contact-block"><small>CUSTOMER</small><strong>${esc(o.customer_name)}</strong><span>${esc(o.contact_number)}</span></div>`:''}</div></section><section class="panel"><div class="panel-head"><h2>Available actions</h2></div><div class="panel-body detail-actions">${o.order_status==='draft'?`${link('#edit/'+o.order_id,'Continue draft','primary full')}${action('review','Review & submit','secondary full')}`:''}${action('refresh',icon('refresh')+'Refresh progress','full')}${canCancel(o)?action('cancel','Cancel order','danger full'):''}${config.demo&&isStaff()&&!['draft','cancelled','completed'].includes(o.order_status)?link('#operations','Open demo operations','quiet full'):''}${o.cancellation_reason?`<div class="cancellation-reason"><small>CANCELLATION REASON</small><p>${esc(o.cancellation_reason)}</p></div>`:''}</div></section></aside></div>`);
}
function operations(requests){shell(`<div class="page-head"><div><div class="eyebrow">AUTHORIZED STAFF AREA</div><h1 tabindex="-1">${config.demo?'Demo operations':'Integration requests'}</h1><p>${config.demo?'Advance a fictional order one verified service result at a time.':'Dispatch requests and check unresolved service results.'}</p></div>${action('refresh',icon('refresh')+'Refresh')}</div><div class="note ${config.demo?'warning':''}">${icon('alert')}<span>${config.demo?'Development simulators only. Every result here is simulated; no live stock, payments, or shipments are changed.':'A timeout remains unresolved. Querying again keeps the original request reference.'}</span></div><section class="panel operations-panel"><div class="panel-head"><h2>Service request queue</h2><span class="result-count">${requests.length} requests</span></div>${requests.length?requests.map(r=>`<article class="request"><div><h3>${esc(label(r.service))} <span>/</span> ${esc(label(r.action))}</h3><div class="request-meta">${badge(r.status)}<a href="#order/${r.order_id}">View order #${r.order_id}</a><small>${r.attempts} attempts</small></div><small class="technical-reference">${esc(r.request_reference)}</small>${r.last_error?`<p class="request-error">${esc(r.last_error)}</p>`:''}</div><div class="actions">${!['done','blocked'].includes(r.status)?`${config.demo?`<label>Simulate result<select data-outcome="${esc(r.request_reference)}"><option value="success">Success</option><option value="timeout">Timeout / unresolved</option>${r.action==='reserve'||r.action==='verify'?'<option value="reject">Reject / fail</option>':''}${r.action==='confirm'?'<option value="expired">Stock expired</option>':''}${r.service==='billing'&&r.action==='cancel'?'<option value="paid">Late payment</option>':''}</select></label>`:''}${action('dispatch',config.demo?'Simulate result':'Dispatch / query','primary',`data-ref="${esc(r.request_reference)}"`)}`:'<span class="recorded">'+icon('check')+'Recorded</span>'}</div></article>`).join(''):`<div class="empty"><span class="empty-icon">${icon('box')}</span><h3>No service requests yet</h3><p>Submit an order to request its stock reservation.</p>${link('#orders','Back to orders','primary')}</div>`}</section>`,'operations');}
function openModal(title,content){modal.setAttribute('aria-labelledby','modal-title');modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2>${action('close-modal',icon('close'),'icon-button','aria-label="Close dialog"')}</div>${content}`;modal.showModal();}
async function review(){quote=await api(`/orders/${order.order_id}/review`,'POST',{});openModal('Review your order',`<p>Confirm the recipient and current purchase details.</p>${reviewContent(true)}`);}
async function submitOrder(){const accepted=document.querySelector('#accept-prices');if(!accepted?.checked)return formError('Accept the current prices to continue.');const key=`submit:${order.order_id}:${quote.version}`;let ref=sessionStorage.getItem(key);if(!ref){ref=crypto.randomUUID();sessionStorage.setItem(key,ref);}try{await api(`/orders/${order.order_id}/submit`,'POST',{submission_reference:ref,version:quote.version,acceptance:quote.acceptance});modal.close();toast('Order submitted. Waiting for stock confirmation.');if(location.hash===`#order/${order.order_id}`)await route();else location.hash=`order/${order.order_id}`;}catch(error){if(error.details?.quote){quote=error.details.quote;if(modal.open){openReviewAgain();}else{draftView();}formError('The names or prices changed. Review the revised details and accept them again.',modal.open?modal:document);}else formError(error.message,modal.open?modal:document);}}
function openReviewAgain(){modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">Review updated prices</h2>${action('close-modal',icon('close'),'icon-button','aria-label="Close dialog"')}</div>${reviewContent(true)}`;}
function cancellationDialog(){openModal('Cancel this order?',`<p>${order.order_status==='draft'?'Your draft will be marked cancelled and kept in your order history.':'We’ll request payment checks and stock release. Cancellation stays pending until both are verified.'}</p><form id="cancel-form" novalidate><div class="error" data-form-error role="alert" tabindex="-1" hidden></div><label>Reason for cancellation<textarea name="reason" required maxlength="1000" placeholder="Tell us why you want to cancel" aria-describedby="error-reason"></textarea>${fieldError('reason')}</label><div class="actions modal-actions">${action('close-modal','Keep order')}<button type="submit" class="danger">${order.order_status==='draft'?'Cancel draft':'Request cancellation'}</button></div></form>`);}
function customerDialog(){captureDraft();openModal('Add a customer',`<p>Save the contact details for this order.</p><form id="customer-form" novalidate><div class="error" data-form-error role="alert" tabindex="-1" hidden></div><label>Customer name<input name="customer_name" required maxlength="150" autocomplete="name" aria-describedby="error-customer_name">${fieldError('customer_name')}</label><label>Email <span class="optional">Optional</span><input name="email" type="email" maxlength="255" autocomplete="email" aria-describedby="error-email">${fieldError('email')}</label><label>Contact number<input name="contact_number" required maxlength="30" type="tel" autocomplete="tel" aria-describedby="error-contact_number">${fieldError('contact_number')}</label><div class="actions modal-actions">${action('close-modal','Cancel')}<button type="submit" class="primary">Create customer</button></div></form>`);}
document.addEventListener('submit',async event=>{
 event.preventDefault();const form=event.target,button=form.querySelector('button[type="submit"]');
 try{
  if(form.id==='login-form'){if(busy.has('login'))return;const data=Object.fromEntries(new FormData(form)),errors={};if(!data.email?.trim()||!/^\S+@\S+\.\S+$/.test(data.email))errors.email='Enter a valid email address.';if(!data.password)errors.password='Enter your password.';if(!showErrors(errors,form))return;formError('',form);await processing('login',button,async()=>{try{await signIn(data.email,data.password);}catch(error){formError(error.message,form);form.querySelector('[name="password"]').value='';form.querySelector('[name="password"]').focus();}},'Signing in…');}
  if(form.id==='filter-form'){const params=new URLSearchParams();for(const[k,v]of new FormData(form))if(v.trim())params.set(k,v.trim());if(params.get('from')&&params.get('to')&&params.get('from')>params.get('to')){document.querySelector('[data-error-for="dates"]').textContent='The end date must be on or after the start date.';return;}page=1;sessionStorage.setItem('orderFilters',params.toString());await route();}
  if(form.id==='customer-form'){const data=Object.fromEntries(new FormData(form)),errors={};if(!data.customer_name.trim())errors.customer_name='Enter the customer name.';if(!data.contact_number.trim())errors.contact_number='Enter a contact number.';if(data.email&&!/^\S+@\S+\.\S+$/.test(data.email))errors.email='Enter a valid email address.';if(!showErrors(errors,form))return;await processing('customer',button,async()=>{try{const result=await api('/customers','POST',data);customers=await api('/customers');draft.customer_id=result.customer_id;modal.close();draftView('[name="customer_id"]');toast('Customer added.');}catch(error){formError(error.message,form);}},'Saving customer…');}
  if(form.id==='cancel-form'){const data=Object.fromEntries(new FormData(form));if(!showErrors(data.reason.trim()?{}:{reason:'Enter a cancellation reason.'},form))return;await processing('cancel',button,async()=>{try{await api(`/orders/${order.order_id}/cancel`,'POST',data);modal.close();await route();toast('Cancellation request recorded.');}catch(error){formError(error.message,form);}},'Requesting cancellation…');}
 }catch(error){formError(error.message,form);}
});
document.addEventListener('input',event=>{const name=event.target.name;if(name){event.target.removeAttribute('aria-invalid');const el=event.target.closest('form')?.querySelector(`[data-error-for="${name}"]`);if(el)el.textContent='';}if(event.target.closest('#draft-form'))captureDraft();});
document.addEventListener('change',event=>{
 const target=event.target;
 if(target.closest('#draft-form'))captureDraft();
 if(target.id==='seller-select'){captureDraft();const next=Number(target.value);if(draft.items.length&&next!==Number(draft.seller_id)&&!confirm('Changing seller clears your selected items. Continue?')){target.value=draft.seller_id;return;}draft.seller_id=next;draft.items=[];quote=null;draftView('#seller-select');}
 if(target.dataset.quantity){const n=Number(target.value),item=draft.items.find(i=>i.offer_id===Number(target.dataset.quantity));item.quantity=n;if(!Number.isSafeInteger(n)||n<1||n>100000){target.setAttribute('aria-invalid','true');let error=target.parentElement.querySelector('.quantity-error');if(!error){error=document.createElement('span');error.className='field-error quantity-error';target.parentElement.append(error);}error.textContent='Use a whole number, 1–100,000.';return;}draftView(`[data-quantity="${item.offer_id}"]`);}
 if(target.id==='accept-prices')document.querySelector('[data-action="submit-order"]').disabled=!target.checked;
});
document.addEventListener('click',async event=>{
 if(event.target.closest('.skip-link')){event.preventDefault();document.querySelector('#main-content')?.focus();return;}const button=event.target.closest('[data-action]');if(!button)return;const name=button.dataset.action;if((busy.has('draft-mutation')||busy.has('submit'))&&['stage','stage-next','add-item','remove-item','save-draft','edit-draft'].includes(name))return;
 try{
  if(name==='toggle-password'){const input=document.querySelector('#password-input'),show=input.type==='password';input.type=show?'text':'password';button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',show?'Hide password':'Show password');button.querySelector('span').textContent=show?'Hide':'Show';return;}
  if(name==='demo-login')return await processing('login',button,async()=>{try{await signIn(button.dataset.email,'CampusDemo2026!');}catch(error){formError(error.message,document.querySelector('#login-form'));}},'Signing in…');
  if(name==='logout')return await processing('logout',button,async()=>{await api('/logout','POST',{});me=null;csrf='';draft=null;quote=null;epoch++;modal.close();login();},'Signing out…');
  if(name==='refresh')return await processing('refresh',button,route,'Refreshing…');
  if(name==='close-modal'){modal.close();return;}
  if(name==='status-filter'){const p=filters();if(button.dataset.status)p.set('status',button.dataset.status);else p.delete('status');sessionStorage.setItem('orderFilters',p.toString());page=1;return await route();}
  if(name==='reset-filters'){sessionStorage.removeItem('orderFilters');page=1;return await route();}
  if(name==='page-prev'||name==='page-next'){page+=name==='page-prev'?-1:1;return await route();}
  if(name==='stage'){captureDraft();const next=Number(button.dataset.stage);if(next<=stage){stage=next;quote=null;draftView();headingFocus();}return;}
  if(name==='stage-next')return await processing('draft-mutation',button,advanceStage,stage===1?'Continuing…':'Saving & checking prices…');
  if(name==='add-item'){const id=Number(button.dataset.id),existing=draft.items.find(i=>i.offer_id===id);if(existing){if(existing.quantity>=100000)return toast('The maximum quantity is 100,000 per offer.');existing.quantity++;}else draft.items.push({offer_id:id,quantity:1});draftView(`[data-action="add-item"][data-id="${id}"]`);toast('Item added to your order.');return;}
  if(name==='remove-item'){draft.items=draft.items.filter(i=>i.offer_id!==Number(button.dataset.id));draftView('[data-action="stage-next"]');return;}
  if(name==='save-draft')return await processing('draft-mutation',button,async()=>{if(draft.items.some(i=>!Number.isSafeInteger(i.quantity)||i.quantity<1||i.quantity>100000))return formError('Fix the item quantities before saving.');const result=await persistDraft();toast('Draft saved. You can continue it any time.');location.hash=`order/${result.order_id}`;},'Saving draft…');
  if(name==='new-customer'){customerDialog();return;}
  if(name==='review')return await processing('review',button,review,'Checking current prices…');
  if(name==='edit-draft'){modal.close();location.hash=`edit/${order.order_id}`;return;}
  if(name==='submit-order')return await processing('submit',button,submitOrder,'Submitting…');
  if(name==='cancel'){cancellationDialog();return;}
  if(name==='dispatch')return await processing('dispatch',button,async()=>{const ref=button.dataset.ref,select=[...document.querySelectorAll('[data-outcome]')].find(e=>e.dataset.outcome===ref);const result=await api('/operations/dispatch','POST',{request_reference:ref,outcome:select?.value||'success'});await route();toast(result.pending?'Result unresolved. Query again using the same request.':config.demo?'Simulated service result recorded.':'Service result recorded.');},'Checking result…');
 }catch(error){formError(error.message,modal.open?modal:document);}
});
window.addEventListener('hashchange',()=>{if(location.hash==='#main-content'){document.querySelector('#main-content')?.focus();return;}route();});
try{config=await api('/config');try{const result=await api('/me');me=result.user;csrf=result.csrf;}catch(error){if(error.status!==401)throw error;}await route();}catch(error){app.innerHTML=`<main class="connection-error"><span class="empty-icon">${icon('alert')}</span><h1>We couldn’t connect</h1><p>${esc(error.message)}</p><button type="button" id="reconnect">Try again</button></main>`;document.querySelector('#reconnect').addEventListener('click',()=>location.reload());}



}
start().catch(error=>{
 console.error('CampusERP startup failed:',error);
 const panel=document.createElement('main');panel.className='connection-error';panel.setAttribute('role','alert');
 const title=document.createElement('h1');title.textContent='We couldn’t load CampusERP';
 const message=document.createElement('p');message.textContent='If you just updated the project, restart the local server with npm.cmd run demo, then try again.';
 const retry=document.createElement('button');retry.type='button';retry.id='startup-retry';retry.className='primary';retry.textContent='Try again';retry.addEventListener('click',()=>location.reload());
 panel.append(title,message,retry);document.querySelector('#app').replaceChildren(panel);
});
